insert into public.policy_areas (slug, label, description, sort_order) values
  ('tax-incentives', 'Tax & Incentives', 'Federal clean-energy credits and location or sourcing bonuses.', 0),
  ('grid-transmission', 'Grid & Transmission', 'Generator interconnection and long-term transmission planning reforms.', 1),
  ('permitting-siting', 'Permitting & Siting', 'Federal environmental review, permitting, and siting policy.', 2),
  ('trade-supply-chain', 'Trade & Supply Chain', 'Trade remedies and supply conditions affecting renewable-energy deployment.', 3),
  ('offshore-wind', 'Offshore Wind', 'Federal leasing and permitting policy specific to offshore wind.', 4);
insert into public.policies (policy_id, policy_area_slug, source_policy_area, policy_title, short_summary, legal_status, implementation_status, litigation_status, status_as_of, status_explanation, effective_requirements, inactive_or_limited_scope, lead_agencies, affected_entities, next_milestone, confidence, review_status, sort_order) values
  ('POL-001', 'tax-incentives', 'Federal clean-energy tax credits', 'Technology-neutral clean-electricity credits under IRC sections 45Y and 48E', 'Sections 45Y and 48E provide technology-neutral production and investment credits under final regulations effective January 15, 2025. Public Law 119-21 later added a wind-and-solar termination rule and prohibited-foreign-entity eligibility restrictions addressed in Notices 2025-42 and 2026-15.', 'in_force', 'guidance_issued', 'none_identified', '2026-07-26', 'The statutory credits and T.D. 10024 final regulations are in force. For applicable wind and solar facilities, the post-2027 termination applies when construction begins after July 4, 2026; Notice 2025-42 supplies the beginning-of-construction rules. Public Law 119-21 also added prohibited-foreign-entity restrictions, for which Notice 2026-15 provides interim safe harbors and reliance rules pending proposed regulations.', 'Apply the statutory and final-regulation eligibility rules, including a greenhouse-gas emissions rate not greater than zero; for applicable wind or solar facilities, apply Notice 2025-42 to the statutory termination timing; and for facilities or energy storage technology within the applicable construction window, evaluate prohibited-foreign-entity status and material-assistance restrictions using Public Law 119-21 and Notice 2026-15 reliance rules.', 'The special wind-and-solar termination is limited to applicable facilities as defined by Public Law 119-21; it does not itself establish that every other 45Y or 48E technology is unavailable.', array['Department of the Treasury', 'Internal Revenue Service']::text[], array['clean-electricity project developers', 'owners of wind facilities', 'owners of solar facilities', 'tax-credit investors', 'applicable entities using elective payment']::text[], 'December 31, 2027 placed-in-service boundary for applicable wind and solar facilities; forthcoming proposed prohibited-foreign-entity regulations are also material.', 'medium', 'verified', 0),
  ('POL-002', 'tax-incentives', 'Federal clean-energy tax-credit bonus', 'Domestic-content bonus-credit requirements for clean-energy credits', 'The domestic-content bonus is available when statutory steel, iron, and manufactured-product requirements are met; IRS Notice 2025-08 provides an updated elective safe harbor and certification and recordkeeping directions.', 'in_force', 'guidance_issued', 'none_identified', '2026-07-26', 'The IRA statutory bonus remains available subject to its requirements. Notice 2025-08 provides reliance rules and an elective safe harbor; it does not replace the statutory domestic-content test.', 'A taxpayer must satisfy the domestic-content requirement, attach the Domestic Content Certification Statement to the applicable return, and retain substantiating records; taxpayers relying on the updated elective safe harbor must make the affirmative election and apply one safe harbor consistently.', 'The notice''s reliance windows and elective safe harbors are limited by their stated beginning-of-construction and future-modification conditions; no conclusion is made here about qualification of a particular component or project.', array['Department of the Treasury', 'Internal Revenue Service']::text[], array['clean-energy project developers', 'manufacturers', 'EPC contractors', 'tax-credit claimants', 'applicable entities using elective payment']::text[], 'Any future IRS modification, update, or withdrawal of the First Updated Elective Safe Harbor affects its stated reliance window.', 'medium', 'verified', 1),
  ('POL-003', 'tax-incentives', 'Federal clean-energy tax-credit bonus', 'Energy-community bonus-credit implementation', 'Energy-community bonus amounts or rates apply when statutory location requirements are met; Notice 2026-39 is the current annual statistical-area and coal-closure update, applicable for listed statistical areas from June 9, 2026 and adding coal-closure and correction tracts.', 'in_force', 'guidance_issued', 'none_identified', '2026-07-26', 'The statutory energy-community provisions remain in force. Notice 2026-39 supplies the current Statistical Area and new Coal Closure information, while preserving the cumulative use of specified earlier coal-closure appendices. The annual notice does not address Brownfield-category determinations.', 'Determine whether the project meets the applicable statutory energy-community category. For current Statistical Area status, use Notice 2026-39 from June 9, 2026 until the next annual list. For Coal Closure status, combine the current notice''s appendices with the earlier appendices it identifies, including retroactive correction treatment stated for Appendix 3.', 'Notice 2026-39 does not provide Brownfield Category information and its appendices are not applicable to the section 48C qualifying advanced energy project credit.', array['Department of the Treasury', 'Internal Revenue Service']::text[], array['clean-energy project developers', 'project owners', 'tax-credit investors', 'communities near fossil-energy employment or coal closures']::text[], 'The next IRS annual energy-community notice based on 2026 unemployment rates, expected in 2027; project-specific location and timing review remains necessary.', 'medium', 'verified', 2),
  ('POL-004', 'trade-supply-chain', 'Solar trade remedies and project supply', '2025 four-country crystalline-silicon photovoltaic AD/CVD order set', 'Commerce issued AD/CVD orders on crystalline silicon photovoltaic cells and covered modules from Cambodia, Malaysia, Thailand, and Vietnam after affirmative Commerce and USITC determinations; the July 2025 correction controls specified Vietnam scope and Malaysia exclusion corrections.', 'in_force', 'implementing', 'none_identified', '2026-07-26', 'The June 2025 AD orders were corrected in the July 2025 Federal Register notice. The record identifies scope and producer/exporter limitations rather than assigning a single duty rate to all imports.', 'For covered crystalline silicon photovoltaic cells and modules from the four named countries, apply the written scope of the AD/CVD orders, including the July 2025 correction; importers must evaluate country, product scope, and applicable producer/exporter treatment.', 'The orders exclude specified products and the correction states that the Hanwha Q Cells Malaysia producer/exporter combination is excluded from the Malaysia AD order; the written scope is dispositive over HTSUS headings supplied for convenience.', array['Department of Commerce, International Trade Administration', 'United States International Trade Commission', 'U.S. Customs and Border Protection']::text[], array['solar-module importers', 'solar project developers', 'EPC contractors', 'module manufacturers', 'customs brokers']::text[], 'Monitor Commerce scope rulings, administrative reviews, and Customs implementation for covered imports.', 'medium', 'verified', 3),
  ('POL-005', 'grid-transmission', 'generator_interconnection', 'FERC Order No. 2023 generator-interconnection reforms', 'Order No. 2023 revises FERC''s pro forma generator-interconnection procedures and agreements through a first-ready, first-served cluster-study process, readiness requirements, study deadlines and penalties, and technology-related reforms.', 'in_force', 'implementing', 'pending', '2026-07-26', 'Order No. 2023 became effective on 2023-11-06 and remains in force as modified by the October 25, 2023 limited rehearing order, Order No. 2023-A, and the August 20, 2024 errata notice. FERC stated in June 2026 that rulewide compliance was not fully complete. The D.C. Circuit heard Advanced Energy United v. FERC on 2025-09-26, and a FERC brief filed 2026-05-20 states that the challenges remained pending; official searches through 2026-07-26 located no later controlling disposition.', 'Public-utility transmission providers must revise their interconnection procedures and agreements to comply with the Order No. 2023 legal chain, subject to Commission-approved compliance filings and permitted variations.', 'The rule does not itself establish one tariff-effective date for every transmission provider. Provider-specific compliance outcomes are not treated here as order-wide completion findings.', array['Federal Energy Regulatory Commission']::text[], array['public utility transmission providers', 'RTOs and ISOs', 'generation and storage interconnection customers', 'ratepayers']::text[], 'Continue provider-specific compliance proceedings and monitor D.C. Circuit No. 23-1282, et al., for disposition.', 'medium', 'verified', 4),
  ('POL-006', 'grid-transmission', 'regional_transmission_planning', 'FERC Order No. 1920 long-term regional transmission planning and cost allocation', 'Order No. 1920 requires long-term regional transmission planning and ex ante cost-allocation processes; Orders No. 1920-A and 1920-B modify and clarify the rule, including state participation and cost-allocation provisions.', 'in_force', 'phased_implementation', 'pending', '2026-07-26', 'Order No. 1920 became effective on 2024-08-12, and Order No. 1920-A''s changes became effective on 2025-01-06 as confirmed by Order No. 1920-B. FERC''s order-wide compliance schedule lists two regional filings and deadlines extending into 2027. FERC''s current case page and 2026-01-05 respondent brief document consolidated Fourth Circuit review in Appalachian Voices v. FERC, Nos. 24-1650, et al.; official searches through 2026-07-26 located no later controlling disposition.', 'Transmission providers must conduct long-term regional planning using at least three long-term scenarios over a 20-year-or-longer horizon, establish ex ante cost-allocation method(s), engage relevant state entities, and make the required regional compliance filings.', 'Compliance schedules and tariff outcomes differ by transmission-planning region. This record does not treat any one region''s filing, extension, or Commission action as nationwide completion or acceptance.', array['Federal Energy Regulatory Commission']::text[], array['public utility transmission providers', 'RTOs and ISOs', 'state utility and siting authorities', 'transmission customers', 'interconnection customers']::text[], 'Regional first and interregional compliance-filing deadlines continue through 2026-2027; monitor Appalachian Voices v. FERC, Nos. 24-1650, et al. (4th Cir.).', 'medium', 'verified', 5),
  ('POL-007', 'permitting-siting', 'permitting', 'CEQ NEPA-regulation rescission and agency-specific implementation transition', 'CEQ''s government-wide NEPA implementing regulations at 40 CFR parts 1500-1508 were removed; agencies continue to implement the NEPA statute through their own procedures, which are being revised or have been revised.', 'in_force', 'phased_implementation', 'none_identified', '2026-07-26', 'CEQ''s final rule, effective January 8, 2026, adopted the rescission without change. CEQ''s September 2025 guidance directs a continuing agency-specific transition, and DOI finalized its own updated procedures on February 24, 2026. No litigation directly challenging the CEQ rescission was identified; Seven County is interpretive NEPA precedent, not rescission litigation.', 'Federal agencies must implement NEPA''s statutory environmental-review requirements and develop methods and procedures in consultation with CEQ. | CEQ''s former 40 CFR parts 1500-1508 are removed from the CFR. | DOI applies its revised 43 CFR part 46 provisions and DOI NEPA Handbook to DOI processes.', 'The rescission does not repeal or amend the NEPA statute. | DOI''s 2026 rule is agency-specific and does not itself set procedures for other agencies. | Seven County concerns review of an STB railway approval; it is controlling precedent on NEPA judicial review, not a project approval for renewable energy.', array['Council on Environmental Quality', 'Department of the Interior', 'Federal permitting agencies']::text[], array['Federal agencies conducting environmental review', 'Renewable-energy project sponsors needing federal approvals', 'States, Tribes, and public participants in federal reviews']::text[], 'Agency-specific procedure revisions and any later court challenge or legislative change; no single CEQ replacement regulation is identified in the reviewed sources.', 'high', 'verified', 6),
  ('POL-008', 'offshore-wind', 'offshore_wind', 'Federal offshore-wind policy: operative OCS leasing withdrawal and vacated permitting pause', 'The January 20, 2025 Presidential Memorandum has a mixed current effect: Section 1''s OCS wind-leasing withdrawal remains operative, while the agency-wide permitting pause implementing Section 2(a) was declared unlawful and vacated on December 8, 2025; the First Circuit entered judgment dismissing the government''s voluntary appeal on June 15, 2026.', 'partially_vacated', 'delayed', 'decided', '2026-07-26', 'Section 1 states that the OCS leasing withdrawal remains until revoked and was expressly outside New York v. Trump. The District of Massachusetts vacated the agencies'' Section 2(a) Wind Order on December 8, 2025. On June 15, 2026, the First Circuit entered judgment voluntarily dismissing appeal No. 26-1174 and ordered the mandate to issue forthwith, leaving the district judgment undisturbed. The `delayed` implementation value reflects continuing unavailability of new OCS leasing under Section 1, not continued implementation of the vacated Section 2(a) pause.', 'Section 1 continues to withdraw all OCS areas from disposition for new or renewed wind-energy leasing until the memorandum is revoked. | Existing lease rights remain unaffected by Section 1''s text, subject to separate lawful project- or lease-specific actions.', 'The agency-wide Wind Order implementing Section 2(a)''s permitting pause was declared unlawful and vacated; it is not treated as an active approval moratorium. | Section 1 was not at issue in New York v. Trump and remains separate from the vacated Section 2(a) implementation. | Later BOEM project suspensions and injunctions are project-specific and do not change the government-wide Section 1/Section 2(a) split.', array['Department of the Interior', 'Bureau of Ocean Energy Management', 'Council on Environmental Quality', 'Other relevant federal agencies']::text[], array['Prospective OCS wind lessees', 'Existing OCS wind lessees', 'Offshore-wind project developers seeking federal approvals', 'State and Tribal governments participating in reviews']::text[], 'Revocation or modification of the Section 1 leasing withdrawal, completion or publication of the federal review, or a new lawful leasing or permitting action; New York v. Trump is closed after appeal dismissal.', 'high', 'verified', 7);
insert into public.policy_documents (document_id, document_type, title, issuing_body, publication_date, effective_date, official_identifier, official_page_url, official_text_url, citation_locator, proposition_supported, source_tier, document_effect, link_checked_at, link_status, is_legal_anchor, notes) values
  ('DOC-001', 'Public Law', 'Public Law 119-21, sections 70512 and 70513', 'United States Congress', '2025-07-04', '2025-07-04', 'Public Law 119-21, 139 Stat. 72', 'https://www.govinfo.gov/link/plaw/119/public/21', 'https://www.govinfo.gov/content/pkg/PLAW-119publ21/pdf/PLAW-119publ21.pdf', 'sections 70512-70513, 139 Stat. 252-263', 'Amends sections 45Y and 48E to add the applicable wind-and-solar termination timing and prohibited-foreign-entity restrictions.', 1, 'effective', '2026-07-26', 'working', false, 'Controlling statutory source for the 2025 termination and eligibility amendments.'),
  ('DOC-002', 'Final rule', 'Section 45Y Clean Electricity Production Credit and Section 48E Clean Electricity Investment Credit', 'Department of the Treasury and Internal Revenue Service', '2025-01-15', '2025-01-15', 'T.D. 10024; 90 FR 4006; RIN 1545-BR17', 'https://www.federalregister.gov/documents/2025/01/15/2025-00196/section-45y-clean-electricity-production-credit-and-section-48e-clean-electricity-investment-credit', 'https://www.govinfo.gov/content/pkg/FR-2025-01-15/pdf/2025-00196.pdf', '90 FR 4006; 26 CFR 1.45Y-1 through 1.45Y-5 and 1.48E-1 through 1.48E-5', 'Final regulations implement sections 45Y and 48E, including qualified-facility and emissions-rate eligibility, credit computation, and domestic-content and energy-community increases.', 1, 'effective', '2026-07-26', 'working', false, 'The final regulations predate Public Law 119-21; they must be applied together with later statutory amendments and guidance.'),
  ('DOC-003', 'IRS notice', 'Notice 2025-42, Beginning of Construction Requirements for Purposes of the Termination of Clean Electricity Production Credits and Clean Electricity Investment Credits for Applicable Wind and Solar Facilities', 'Internal Revenue Service', '2025-09-02', '2025-09-02', 'Notice 2025-42, 2025-36 I.R.B.', 'https://www.irs.gov/irb/2025-36_IRB', 'https://www.irs.gov/irb/2025-36_IRB#NOT-2025-42', 'sections 1, 2.01, and 7', 'Provides beginning-of-construction guidance for the statutory termination provisions and states that the deadline applies to applicable wind and solar facilities whose construction begins after July 4, 2026.', 1, 'effective', '2026-07-26', 'working', false, 'The notice is effective for applicable wind and solar facilities whose construction did not begin before September 2, 2025; it modifies Notice 2022-61 only as specified.'),
  ('DOC-004', 'IRS notice', 'Notice 2026-15, Guidance to Apply Interim Safe Harbors for Purposes of Determining a Taxpayer''s Material Assistance from a Prohibited Foreign Entity; Other Prohibited Foreign Entity Guidance', 'Internal Revenue Service', '2026-03-09', '2026-03-09', 'Notice 2026-15, 2026-11 I.R.B. 658', 'https://www.irs.gov/irb/2026-11_IRB', 'https://www.irs.gov/irb/2026-11_IRB#NOT-2026-15', 'sections 1, 3-5, 8-9', 'Provides interim rules and safe harbors for prohibited-foreign-entity status and material-assistance cost ratios under sections 45Y and 48E, with stated reliance windows pending proposed regulations and safe-harbor tables.', 1, 'effective', '2026-07-26', 'working', false, 'Interim guidance; the notice expressly anticipates forthcoming proposed regulations and other guidance.'),
  ('DOC-005', 'Public Law', 'Public Law 117-169, Inflation Reduction Act of 2022', 'United States Congress', '2022-08-16', '2022-08-16', 'Public Law 117-169, 136 Stat. 1818', 'https://www.govinfo.gov/link/plaw/117/public/169', 'https://www.govinfo.gov/content/pkg/PLAW-117publ169/pdf/PLAW-117publ169.pdf', 'sections 13101, 13102, 13701, and 13702', 'Legal anchor for the Inflation Reduction Act clean-electricity credit structure and associated bonus-credit provisions.', 1, 'effective', '2026-07-26', 'working', true, 'Pre-window document retained only as the necessary statutory anchor, consistent with the brief.'),
  ('DOC-006', 'IRS notice', 'Notice 2024-41, Domestic Content Bonus Credit Amounts under the Inflation Reduction Act of 2022: Expansion of Applicable Projects for Safe Harbor in Notice 2023-38 and New Elective Safe Harbor to Determine Cost Percentages for Adjusted Percentage Rule', 'Internal Revenue Service', '2024-06-10', '2024-05-16', 'Notice 2024-41, 2024-24 I.R.B. 1615', 'https://www.irs.gov/irb/2024-24_IRB', 'https://www.irs.gov/irb/2024-24_IRB#NOT-2024-41', 'sections 3-5 and Table 1', 'Expands listed applicable projects and supplies an elective safe harbor with assigned cost percentages later modified by Notice 2025-08.', 1, 'partially_effective', '2026-07-26', 'working', false, 'Notice 2025-08 modifies this notice; only the provisions preserved by the later reliance rules remain usable.'),
  ('DOC-007', 'IRS notice', 'Notice 2025-08, Domestic Content Bonus Credit Amounts under the Inflation Reduction Act of 2022: First Updated Elective Safe Harbor modifying Notice 2024-41', 'Internal Revenue Service', '2025-02-18', '2025-01-16', 'Notice 2025-08, 2025-8 I.R.B. 800', 'https://www.irs.gov/irb/2025-08_IRB', 'https://www.irs.gov/irb/2025-08_IRB#NOT-2025-08', 'sections 5-7, 10, and 11', 'Updates the elective safe harbor, describes certification and recordkeeping, and provides taxpayer reliance rules for domestic-content bonus-credit requirements.', 1, 'effective', '2026-07-26', 'working', false, 'Use the stated reliance clauses rather than assuming this notice supersedes all earlier domestic-content guidance.'),
  ('DOC-008', 'IRS notice', 'Notice 2025-31, Energy Community Bonus Credit Amounts or Rates: Annual Statistical Area Category Update and Coal Closure Category Update', 'Internal Revenue Service', '2025-07-07', '2025-06-23', 'Notice 2025-31, 2025-28 I.R.B.', 'https://www.irs.gov/irb/2025-28_IRB', 'https://www.irs.gov/irb/2025-28_IRB#NOT-2025-31', 'sections 1-3 and Appendices 1-5', 'Publishes information taxpayers may use for the Statistical Area and Coal Closure categories and explains the relevant 45, 45Y, 48, and 48E bonus framework.', 1, 'partially_effective', '2026-07-26', 'working', false, 'The notice expressly does not provide Brownfield Category information. Its Statistical Area information has been updated by Notice 2026-39; specified Coal Closure appendices remain part of the cumulative list.'),
  ('DOC-009', 'IRS notice', 'Notice 2026-39, Energy Community Bonus Credit Amounts or Rates: Annual Statistical Area Category Update and Coal Closure Category Update', 'Internal Revenue Service', '2026-06-29', '2026-06-09', 'Notice 2026-39, 2026-27 I.R.B. 1', 'https://www.irs.gov/irb/2026-27_irb', 'https://www.irs.gov/irb/2026-27_irb#NOT-2026-39', 'sections 1-3 and Appendices 1-3', 'Updates Statistical Area status effective June 9, 2026, lists new Coal Closure tracts, and identifies correction tracts eligible for taxable years starting after December 31, 2022.', 1, 'effective', '2026-07-26', 'working', false, 'Current annual update as of the assessment date; the notice directs cumulative use of specified earlier coal-closure appendices.'),
  ('DOC-010', 'Federal Register order notice', 'Crystalline Silicon Photovoltaic Cells, Whether or Not Assembled Into Modules From the Socialist Republic of Vietnam: Amended Final Antidumping Duty Determination; Crystalline Silicon Photovoltaic Cells, Whether or Not Assembled Into Modules From Cambodia, Malaysia, Thailand, and the Socialist Republic of Vietnam: Antidumping Duty Orders', 'Department of Commerce, International Trade Administration', '2025-06-24', '2025-06-24', '90 FR 26786; FR Doc. 2025-11588; A-555-003, A-557-830, A-549-851, A-552-841', 'https://www.govinfo.gov/app/details/FR-2025-06-24/2025-11588', 'https://www.govinfo.gov/content/pkg/FR-2025-06-24/pdf/2025-11588.pdf', '90 FR 26786-26791; Antidumping Duty Orders, cash-deposit tables, and scope appendix as corrected by 90 FR 29843', 'Commerce issued the four-country antidumping duty orders and directed assessment and cash-deposit administration, subject to the later July 2025 correction.', 1, 'partially_effective', '2026-07-26', 'working', false, 'Read together with the July 7, 2025 correction for the current Vietnam scope appendix and Malaysia producer/exporter exclusion.'),
  ('DOC-011', 'Federal Register order notice', 'Crystalline Silicon Photovoltaic Cells, Whether or Not Assembled Into Modules, From Malaysia and Thailand: Amended Final Countervailing Duty Determinations; Crystalline Silicon Photovoltaic Cells, Whether or Not Assembled Into Modules, From Cambodia, Malaysia, Thailand, and the Socialist Republic of Vietnam: Countervailing Duty Orders', 'Department of Commerce, International Trade Administration', '2025-06-24', '2025-06-24', '90 FR 26791; FR Doc. 2025-11589; C-555-004, C-557-831, C-549-852, C-552-842', 'https://www.govinfo.gov/app/details/FR-2025-06-24/2025-11589', 'https://www.govinfo.gov/content/pkg/FR-2025-06-24/pdf/2025-11589.pdf', '90 FR 26791-26798; Countervailing Duty Orders, subsidy-rate tables, and Appendices I-II', 'Commerce issued the four-country countervailing duty orders and amended the Malaysia and Thailand final determinations for ministerial errors.', 1, 'effective', '2026-07-26', 'working', false, 'Separate controlling source for the CVD orders; the July 2025 AD correction does not establish or amend these CVD orders.'),
  ('DOC-012', 'Federal Register notice', 'Crystalline Silicon Photovoltaic Cells, Whether or Not Assembled Into Modules From the Socialist Republic of Vietnam: Amended Final Antidumping Duty Determination; Crystalline Silicon Photovoltaic Cells, Whether or Not Assembled Into Modules From Cambodia, Malaysia, Thailand, and the Socialist Republic of Vietnam: Antidumping Duty Orders; Correction', 'Department of Commerce, International Trade Administration', '2025-07-07', '2025-07-07', '90 FR 29843; FR Doc. 2025-12573; A-555-003, A-557-830, A-549-851, A-552-841', 'https://www.federalregister.gov/documents/2025/07/07/2025-12573/crystalline-silicon-photovoltaic-cells-whether-or-not-assembled-into-modules-from-the-socialist', 'https://www.govinfo.gov/content/pkg/FR-2025-07-07/pdf/2025-12573.pdf', '90 FR 29843-29847; Correction 1, Correction 2, and Appendices I-II', 'Corrects the Vietnam scope appendix and the Malaysia Hanwha Q Cells producer/exporter exclusion in the June 2025 antidumping duty orders.', 1, 'effective', '2026-07-26', 'working', false, 'The Federal Register page directs users to the official GovInfo PDF; the correction replaces specified portions of the June 24 order notice.'),
  ('DOC-013', 'USITC final investigation report', 'Crystalline Silicon Photovoltaic Cells, Whether or Not Assembled Into Modules from Cambodia, Malaysia, Thailand, and Vietnam', 'United States International Trade Commission', '2025-06-30', '2025-06-09', 'USITC Publication 5631; Inv. Nos. 701-TA-722-725 and 731-TA-1690-1693 (Final)', 'https://www.usitc.gov/publications/701_731/pub5631.pdf', 'https://www.usitc.gov/publications/701_731/pub5631.pdf', 'Determinations at 1-2 and Views of the Commission', 'Contains the Commission''s final affirmative material-injury and threat determinations and supporting views for the four-country AD/CVD investigations.', 1, 'effective', '2026-07-26', 'working', false, 'The report identifies June 2025; June 30 is used as the publication date because the Commission''s official release stated that the report would be available by that date.'),
  ('DOC-014', 'USITC determination release', 'Crystalline Silicon Photovoltaic Cells, Whether or Not Assembled Into Modules, From Cambodia, Malaysia, Thailand, and Vietnam Injure or Threaten U.S. Industry, Says USITC [Revised]', 'United States International Trade Commission', '2025-05-20', '2025-05-20', 'News Release 25-062; Inv. Nos. 701-TA-722-725 and 731-TA-1690-1693 (Final)', 'https://www.usitc.gov/press_room/news_release/2025/er0520_66998.htm', 'https://www.usitc.gov/press_room/news_release/2025/er0520_66998.htm', 'Determination paragraph and Inv. Nos. 701-TA-722-725 and 731-TA-1690-1693 (Final)', 'USITC made affirmative material-injury or threat determinations, clearing the way for Commerce to issue AD/CVD orders.', 3, 'effective', '2026-07-26', 'working', false, 'Agency release summarizing the Commission''s final determinations; USITC Publication 5631 is the stronger substantive source.'),
  ('DOC-015', 'Commerce final determination release', 'Final Affirmative Determinations in the Antidumping and Countervailing Duty Investigations of Crystalline Photovoltaic Cells Whether or Not Assembled into Modules from Cambodia, Malaysia, Thailand, and the Socialist Republic of Vietnam', 'Department of Commerce, International Trade Administration', '2025-04-21', '2025-04-21', 'Commerce final affirmative determinations, April 21, 2025', 'https://www.trade.gov/final-affirmative-determinations-antidumping-and-countervailing-duty-investigations-crystalline', 'https://www.trade.gov/final-affirmative-determinations-antidumping-and-countervailing-duty-investigations-crystalline', 'Final dumping rates and final subsidy rates', 'Commerce announced final affirmative AD/CVD determinations and provided exporter-specific dumping and cash-deposit rates before the USITC final injury determinations and issuance of orders.', 3, 'effective', '2026-07-26', 'working', false, 'Use the later order correction for the current written scope and specified Malaysia exclusion.'),
  ('DOC-016', 'final_rule', 'Improvements to Generator Interconnection Procedures and Agreements, Order No. 2023', 'Federal Energy Regulatory Commission', '2023-07-28', '2023-11-06', 'RM22-14-000; Order No. 2023; 184 FERC ¶ 61,054; 88 FR 61014', 'https://www.ferc.gov/media/order-no-2023', 'https://www.govinfo.gov/content/pkg/FR-2023-09-06/pdf/2023-16628.pdf', '88 FR 61014, 61014; Order No. 2023 PP 1, 5, 1762, 1785', 'FERC adopted order-wide generator-interconnection reforms, effective November 6, 2023, and required transmission-provider compliance filings.', 1, 'effective', '2026-07-26', 'working', false, 'The canonical FERC landing page and the complete GovInfo Federal Register text were opened.'),
  ('DOC-017', 'rehearing_order', 'Order on Motions and Addressing Limited Arguments Raised on Rehearing and Setting Aside Prior Order, in Part', 'Federal Energy Regulatory Commission', '2023-10-25', null, 'RM22-14-000 and RM22-14-001; 185 FERC ¶ 61,063; Accession No. 20231025-3056', 'https://www.ferc.gov/enforcement-legal/legal/court-cases/advanced-energy-united-et-al-v-ferc-0', 'https://elibrary.ferc.gov/eLibrary/filelist?accession_Number=20231025-3056', '185 FERC ¶ 61,063 at PP 1, 3, 8-11 and ordering paras. A-B', 'On October 25, 2023, FERC addressed limited rehearing arguments and set Order No. 2023 aside in part to extend compliance-filing deadlines.', 1, 'effective', '2026-07-26', 'working', false, 'The FERC appellate case page identifies the timing order by citation, and the official FERC eLibrary accession provides the issuing-agency record. The relationship link carries the amending legal verb.'),
  ('DOC-018', 'rehearing_clarification_order', 'Improvements to Generator Interconnection Procedures and Agreements, Order No. 2023-A', 'Federal Energy Regulatory Commission', '2024-03-21', '2024-05-16', 'RM22-14-001; Order No. 2023-A; 186 FERC ¶ 61,199; 89 FR 27006', 'https://www.ferc.gov/media/e1-rm22-14-001', 'https://www.govinfo.gov/content/pkg/FR-2024-04-16/pdf/2024-06563.pdf', '89 FR 27006, 27006; Order No. 2023-A PP 1-5, 667', 'Order No. 2023-A addressed rehearing arguments, set Order No. 2023 aside in part, clarified it, and became effective May 16, 2024.', 1, 'effective', '2026-07-26', 'working', false, 'The canonical FERC landing page and complete GovInfo Federal Register text were opened.'),
  ('DOC-019', 'errata_notice', 'Improvements to Generator Interconnection Procedures and Agreements, Errata Notice', 'Federal Energy Regulatory Commission', '2024-08-20', null, 'Errata Notice; 188 FERC ¶ 61,134', 'https://www.ferc.gov/media/e-2-er24-2026-000', 'https://www.ferc.gov/sites/default/files/2025-06/E-2-ER24-2026-000.pdf', '191 FERC ¶ 61,230, P 22 & n.466 (identifying Aug. 20, 2024 Errata Notice, 188 FERC ¶ 61,134)', 'FERC issued the August 20, 2024 errata notice with additional revisions to the pro forma LGIP, LGIA, and SGIA and later directed providers to incorporate those revisions.', 1, 'effective', '2026-07-26', 'alternate_official_url', false, 'The opened FERC compliance order expressly identifies the errata''s date, citation, affected forms, and incorporation directive. A standalone public FERC errata PDF did not surface in the reproducible searches, so this transparent alternate official source is used.'),
  ('DOC-020', 'implementation_status_statement', 'Chairman Swett''s Remarks on the Large Load Show Cause Orders, E-7 to E-12', 'Federal Energy Regulatory Commission', '2026-06-18', null, 'June 18, 2026 Open Meeting remarks', 'https://www.ferc.gov/news-events/news/chairman-swetts-remarks-large-load-show-cause-orders-e-7-e-12-june-18-2026-open', 'https://www.ferc.gov/news-events/news/chairman-swetts-remarks-large-load-show-cause-orders-e-7-e-12-june-18-2026-open', 'Remarks at text accompanying nn.8-10', 'FERC stated that Order No. 2023''s compliance process was not fully complete as of June 2026.', 1, 'effective', '2026-07-26', 'working', false, 'This source supports only order-wide implementation status and does not amend the rule or establish the status of any specific provider tariff.'),
  ('DOC-021', 'judicial_review_record', 'Advanced Energy United v. FERC oral-argument record', 'United States Court of Appeals for the District of Columbia Circuit', '2025-09-26', null, 'D.C. Cir. No. 23-1282, et al.', 'https://media.cadc.uscourts.gov/recordings/bydate/2025/9', 'https://media.cadc.uscourts.gov/recordings/bydate/2025/9', 'D.C. Circuit September 2025 oral-argument index; No. 23-1282; argument date Sept. 26, 2025', 'The D.C. Circuit heard oral argument in Advanced Energy United v. FERC on September 26, 2025.', 1, 'effective', '2026-07-26', 'working', false, 'The official court record identifies the docket, case name, panel, advocates, and argument date. It does not itself record a merits disposition.'),
  ('DOC-022', 'appellate_brief', 'Brief for Respondent Federal Energy Regulatory Commission in Vistra Corporation, et al. v. FERC', 'Federal Energy Regulatory Commission', '2026-05-20', null, '5th Cir. Nos. 25-60055, 25-60149, 25-60329, and 25-60453; status reference to D.C. Cir. No. 23-1282, et al.', 'https://www.ferc.gov/enforcement-legal/legal/court-cases/appellate-briefs?page=0', 'https://www.ferc.gov/sites/default/files/2026-05/25-60055-RespondentBrief5-20-26.pdf', 'Respondent brief at 9 n.2', 'In a May 20, 2026 court filing, FERC stated that the Order No. 2023 challenges in D.C. Circuit No. 23-1282, et al., were fully briefed, argued September 26, 2025, and pending.', 1, 'effective', '2026-07-26', 'working', false, 'The brief concerns a different FERC rulemaking but supplies FERC''s current express procedural statement about the Order No. 2023 litigation. No substantive holding from the Vistra case is attributed to Order No. 2023.'),
  ('DOC-023', 'final_rule', 'Building for the Future Through Electric Regional Transmission Planning and Cost Allocation, Order No. 1920', 'Federal Energy Regulatory Commission', '2024-05-13', '2024-08-12', 'RM21-17-000; Order No. 1920; 187 FERC ¶ 61,068; 89 FR 49280', 'https://www.ferc.gov/media/e1-rm21-17-000', 'https://www.govinfo.gov/content/pkg/FR-2024-06-11/pdf/2024-10872.pdf', '89 FR 49280, 49280; Order No. 1920 PP 1, 5, 256, 261, 301, 1769-1770', 'Order No. 1920 adopted long-term regional transmission-planning and cost-allocation reforms and became effective August 12, 2024.', 1, 'effective', '2026-07-26', 'working', false, 'The canonical FERC landing page and complete GovInfo Federal Register text were opened.'),
  ('DOC-024', 'rehearing_clarification_order', 'Building for the Future Through Electric Regional Transmission Planning and Cost Allocation, Order No. 1920-A', 'Federal Energy Regulatory Commission', '2024-11-21', '2025-01-06', 'RM21-17-001; Order No. 1920-A; 189 FERC ¶ 61,126; 89 FR 97174', 'https://www.ferc.gov/media/e-1-rm-21-17-001', 'https://www.govinfo.gov/content/pkg/FR-2024-12-06/pdf/2024-27982.pdf', '89 FR 97174, 97174; Order No. 1920-A PP 1-6 and appendix; effective date confirmed by Order No. 1920-B, 90 FR 17692', 'Order No. 1920-A addressed rehearing arguments, set Order No. 1920 aside in part, clarified it, and made its changes effective January 6, 2025.', 1, 'effective', '2026-07-26', 'working', false, 'The canonical FERC landing page and complete GovInfo text were opened; the effective date is taken from the order text and Order No. 1920-B''s Federal Register confirmation.'),
  ('DOC-025', 'rehearing_clarification_order', 'Building for the Future Through Electric Regional Transmission Planning and Cost Allocation, Order No. 1920-B', 'Federal Energy Regulatory Commission', '2025-04-11', null, 'RM21-17-003; Order No. 1920-B; 191 FERC ¶ 61,026; accession 20250411-3071; 90 FR 17692', 'https://www.ferc.gov/media/order-1920-b', 'https://www.ferc.gov/sites/default/files/2025-04/20250411-3071.PDF', 'Accession 20250411-3071; 191 FERC ¶ 61,026; 90 FR 17692, 17692; Order No. 1920-B PP 1-5', 'Order No. 1920-B addressed rehearing arguments concerning Order No. 1920-A and granted or denied clarification in part while confirming January 6, 2025 as Order No. 1920-A''s effective date.', 1, 'effective', '2026-07-26', 'working', false, 'The canonical FERC landing page, official FERC PDF, and GovInfo text at https://www.govinfo.gov/content/pkg/FR-2025-04-28/pdf/2025-06941.pdf were opened.'),
  ('DOC-026', 'implementation_guidance', 'Order No. 1920 Compliance Filings Schedule', 'Federal Energy Regulatory Commission', '2025-06-16', null, 'FERC Order No. 1920 Guidance', 'https://www.ferc.gov/news-events/news/order-no-1920-compliance-filings-schedule', 'https://www.ferc.gov/news-events/news/order-no-1920-compliance-filings-schedule', 'Order-wide description and regional deadline table; page updated Mar. 12, 2026', 'Order No. 1920 requires two compliance filings, with region-specific deadlines and engagement-period extensions extending through 2027.', 1, 'effective', '2026-07-26', 'working', false, 'This order-wide schedule supports phased implementation only; it is not evidence that any individual regional filing has been accepted.'),
  ('DOC-027', 'judicial_review_record', 'Appalachian Voices, et al. v. FERC', 'Federal Energy Regulatory Commission', '2026-01-05', null, '4th Cir. No. 24-1650, et al.', 'https://www.ferc.gov/enforcement-legal/legal/court-cases/appalachian-voices-et-al-v-ferc-24', 'https://www.ferc.gov/enforcement-legal/legal/court-cases/appalachian-voices-et-al-v-ferc-24', 'FERC appellate-case page, updated Jan. 6, 2026; filed Jan. 5, 2026', 'FERC identifies consolidated Fourth Circuit review of Orders No. 1920, 1920-A, and 1920-B in Appalachian Voices v. FERC, No. 24-1650, et al.', 1, 'effective', '2026-07-26', 'working', false, 'This current FERC case page replaces the stale CAISO compliance motion as the primary litigation record.'),
  ('DOC-028', 'appellate_brief', 'Brief of Respondent Federal Energy Regulatory Commission in Appalachian Voices, et al. v. FERC', 'Federal Energy Regulatory Commission', '2026-01-05', null, '4th Cir. Nos. 24-1650, et al. (consolidated)', 'https://www.ferc.gov/enforcement-legal/legal/court-cases/appalachian-voices-et-al-v-ferc-24', 'https://www.ferc.gov/sites/default/files/2026-01/2026-1-5_24-1650etal.pdf', 'Respondent brief cover, administrative orders under review at 6-7, jurisdictional statement at 9-15', 'FERC filed its merits brief in the consolidated Fourth Circuit petitions for review of Orders No. 1920, 1920-A, and 1920-B on January 5, 2026.', 1, 'effective', '2026-07-26', 'working', false, 'The official FERC case page and linked respondent brief were opened. The brief''s cover stated that oral argument had not yet been scheduled at filing.'),
  ('DOC-029', 'executive_order', 'Unleashing American Energy', 'The White House', '2025-01-20', '2025-01-20', 'Executive Order 14154; 90 FR 8353', 'https://www.whitehouse.gov/presidential-actions/2025/01/unleashing-american-energy/', null, '§ 5(a)-(d)', 'Revokes E.O. 11991; directs CEQ to issue NEPA guidance, propose rescission of 40 CFR part 1500 et seq., and coordinate agency-level revisions.', 1, 'effective', '2026-07-26', 'working', false, 'Government-wide executive direction; it does not itself repeal NEPA.'),
  ('DOC-030', 'final_rule', 'Removal of National Environmental Policy Act Implementing Regulations', 'Council on Environmental Quality', '2026-01-08', '2026-01-08', '91 FR 618; FR Doc. 2026-00178; CEQ-2025-0002', 'https://www.federalregister.gov/documents/2026/01/08/2026-00178/removal-of-national-environmental-policy-act-implementing-regulations', 'https://www.govinfo.gov/content/pkg/FR-2026-01-08/pdf/2026-00178.pdf', '91 FR 618, 618, 620, 622', 'Adopts the 2025 interim final rule without changes and removes all iterations of CEQ''s NEPA implementing regulations from the CFR.', 1, 'effective', '2026-07-26', 'working', false, 'Controlling government-wide regulatory action; it states that agency-specific procedures continue pending revisions.'),
  ('DOC-031', 'final_rule', 'National Environmental Policy Act Implementing Regulations', 'Department of the Interior, Office of the Secretary', '2026-02-24', '2026-02-24', '91 FR 8738; FR Doc. 2026-03708; DOI-2025-0004', 'https://www.doi.gov/oepc/national-environmental-policy-act-nepa', 'https://www.govinfo.gov/content/pkg/FR-2026-02-24/pdf/2026-03708.pdf', '91 FR 8738, 8738-39', 'Finalizes DOI''s partial rescission and targeted revision of 43 CFR part 46 and moves most DOI NEPA procedures to a Departmental Handbook.', 1, 'effective', '2026-07-26', 'working', false, 'Agency-specific implementation; its scope is DOI internal processes, including BOEM, not government-wide procedure.'),
  ('DOC-032', 'supreme_court_opinion', 'Seven County Infrastructure Coalition v. Eagle County, Colorado', 'Supreme Court of the United States', '2025-05-29', '2025-05-29', 'No. 23-975; 605 U.S. 168 (2025); 145 S. Ct. 1497', 'https://www.supremecourt.gov/opinions/24pdf/605us1r34_h3ci.pdf', 'https://www.supremecourt.gov/opinions/24pdf/605us1r34_h3ci.pdf', '605 U.S. 168, 168-70', 'Holds that the D.C. Circuit failed to afford required deference in a NEPA case and that NEPA did not require analysis of separate upstream and downstream projects in that record.', 1, 'effective', '2026-07-26', 'working', false, 'Case-specific merits decision with nationwide precedential effect; it does not decide CEQ''s rescission.'),
  ('DOC-033', 'implementation_guidance', 'Implementation of the National Environmental Policy Act', 'Council on Environmental Quality', '2025-09-29', '2025-09-29', 'CEQ Memorandum for Heads of Federal Departments and Agencies, Sept. 29, 2025', 'https://nepa.gov/document/memorandum-heads-departments-and-agencies-implementation-national-environmental-policy-1', 'https://nepa.gov/sites/default/files/documents/Agency-NEPA-Implementation-Guidance.pdf', 'pp. 1-3, 7-9', 'Provides current nonbinding CEQ guidance for agencies establishing or revising agency-specific NEPA procedures and states that ongoing analyses should continue under existing procedures adjusted for current law and guidance.', 1, 'effective', '2026-07-26', 'working', false, 'Current CEQ implementation guidance; it expressly says it is not mandatory or binding and replaces the February 19, 2025 guidance.'),
  ('DOC-034', 'presidential_memorandum', 'Temporary Withdrawal of All Areas on the Outer Continental Shelf from Offshore Wind Leasing and Review of the Federal Government''s Leasing and Permitting Practices for Wind Projects', 'The White House', '2025-01-29', '2025-01-21', 'Presidential Memorandum, Jan. 20, 2025; 90 FR 8363; FR Doc. 2025-01966', 'https://www.whitehouse.gov/presidential-actions/2025/01/temporary-withdrawal-of-all-areas-on-the-outer-continental-shelf-from-offshore-wind-leasing-and-review-of-the-federal-governments-leasing-and-permitting-practices-for-wind-projects/', 'https://www.govinfo.gov/content/pkg/FR-2025-01-29/pdf/2025-01966.pdf', '90 FR 8363-64, §§ 1-2(a)', 'Section 1 withdraws all OCS areas from wind leasing until revoked and preserves existing lease rights; Section 2(a) directed the later-vacated agency Wind Order.', 1, 'effective', '2026-07-26', 'working', false, 'Controlling for the operative Section 1 withdrawal. Section 2(a)''s agency-wide implementation was later vacated; the memorandum is therefore recorded as mixed/partial.'),
  ('DOC-035', 'agency_implementation_notice', 'Virtual Public Meetings Cancelled for Vineyard Mid-Atlantic Offshore Wind Project', 'Bureau of Ocean Energy Management', '2025-02-04', '2025-02-04', 'BOEM stakeholder notice; Docket BOEM-2025-0002', 'https://www.boem.gov/newsroom/notes-stakeholders/virtual-public-meetings-cancelled-vineyard-mid-atlantic-offshore-wind', null, 'paragraphs 2-3', 'BOEM states that DOI and BOEM are implementing the memorandum and canceled the project''s February public meetings as a result.', 1, 'superseded', '2026-07-26', 'working', false, 'Historical implementation evidence only. The agency-wide Section 2(a) Wind Order was vacated December 8, 2025.'),
  ('DOC-036', 'litigation_status_report', 'FY 2027 Environment and Natural Resources Division Narrative', 'Department of Justice, Environment and Natural Resources Division', '2026-04-06', null, 'FY 2027 Performance Budget Congressional Budget Submission', 'https://www.justice.gov/doj/fy-2027-budget-and-performance-summary', 'https://www.justice.gov/jmd/media/1434231/dl?inline=', 'p. 5, active-pending-litigation bullet', 'Identifies New York v. Trump (D. Mass.) as active pending litigation by 17 States and the District of Columbia challenging the January 2025 offshore-wind memorandum.', 1, 'superseded', '2026-07-26', 'working', false, 'Historical context only. Its pending-status statement was superseded by the district judgment and June 15, 2026 appeal dismissal.'),
  ('DOC-037', 'district_court_order', 'State of New York, et al. v. Donald J. Trump, et al. — Memorandum and Order', 'U.S. District Court for the District of Massachusetts', '2025-12-08', '2025-12-08', 'No. 25-cv-11221-PBS; ECF No. 234; 2025 WL 3514301', 'https://ag.ny.gov/press-release/2025/attorney-general-james-wins-lawsuit-defending-wind-energy', 'https://ag.ny.gov/sites/default/files/court-filings/state-of-new-york-et-al-alliance-for-clean-energy-new-york-v-donald-trump-et-al-order-2025.pdf', 'ECF No. 234, pp. 1-4, 32-33, 47', 'Expressly excludes Section 1 from the litigation, holds the agencies'' Section 2(a) Wind Order arbitrary, capricious, and contrary to law, and vacates that Wind Order.', 1, 'vacated', '2026-07-26', 'working', false, 'Court-filed order hosted by the Office of the New York Attorney General, an official government source. Relief is government-wide as to the agency Wind Order; Section 1''s OCS leasing withdrawal was not at issue.'),
  ('DOC-038', 'appellate_judgment', 'State of New York, et al. v. Donald J. Trump, et al. — Judgment', 'U.S. Court of Appeals for the First Circuit', '2026-06-15', '2026-06-15', 'No. 26-1174; Document 00118461865; Entry ID 6818134', 'https://www.mass.gov/news/ag-campbell-secures-final-victory-as-court-dismisses-trump-administrations-appeal-in-case-over-federal-offshore-wind-permitting-pause', 'https://www.mass.gov/doc/doj-wind-dismissal/download', 'Judgment; docket header (No. 26-1174, Document 00118461865, filed and entered June 15, 2026, Entry ID 6818134)', 'The First Circuit entered judgment voluntarily dismissing the federal defendants-appellants'' appeal and ordered the mandate to issue forthwith, leaving the district-court judgment undisturbed.', 1, 'effective', '2026-07-26', 'working', false, 'Court-generated CM/ECF judgment hosted on an official Commonwealth of Massachusetts site. No First Circuit own-domain public URL was located in the reviewed sources; the dismissal was procedural, not a merits affirmance.');
insert into public.policy_document_links (link_id, policy_id, document_id, relationship_type, relationship_summary, scope_affected, valid_from, valid_to, is_controlling_source) values
  ('LNK-001', 'POL-001', 'DOC-001', 'amends', 'Public Law 119-21 amends the 45Y and 48E rules for applicable wind and solar facilities.', 'Applicable wind and solar facilities under sections 45Y and 48E', '2025-07-04', null, true),
  ('LNK-002', 'POL-001', 'DOC-002', 'implements', 'T.D. 10024 implements the core 45Y and 48E qualification, emissions-rate, computation, and coordination rules.', 'Qualified facilities and energy storage technology placed in service after 2024', '2025-01-15', null, true),
  ('LNK-003', 'POL-001', 'DOC-003', 'implements', 'Notice 2025-42 supplies beginning-of-construction guidance for the statutory termination rule.', 'Applicable wind and solar facilities', '2025-09-02', null, true),
  ('LNK-004', 'POL-001', 'DOC-004', 'implements', 'Notice 2026-15 provides interim prohibited-foreign-entity safe harbors and reliance rules pending further regulations and tables.', '45Y qualified facilities and 48E qualified facilities or energy storage technology within the stated reliance windows', '2026-03-09', null, true),
  ('LNK-005', 'POL-002', 'DOC-005', 'enacts', 'The Inflation Reduction Act is the statutory anchor for the clean-energy credit and bonus structure.', 'Domestic-content bonus-credit claimants', '2022-08-16', null, true),
  ('LNK-006', 'POL-002', 'DOC-002', 'implements', 'T.D. 10024 includes domestic-content credit-increase rules for sections 45Y and 48E.', '45Y and 48E domestic-content bonus claimants', '2025-01-15', null, true),
  ('LNK-007', 'POL-002', 'DOC-006', 'implements', 'Notice 2024-41 expanded applicable projects and supplied an elective assigned-cost safe harbor later modified by Notice 2025-08.', 'Specified domestic-content applicable projects', '2024-05-16', null, false),
  ('LNK-008', 'POL-002', 'DOC-007', 'implements', 'Notice 2025-08 updates the elective safe harbor and reliance guidance.', 'Projects claiming a domestic-content bonus credit', '2025-01-16', null, true),
  ('LNK-009', 'POL-003', 'DOC-005', 'enacts', 'The Inflation Reduction Act is the statutory anchor for the clean-electricity bonus framework.', 'Energy-community bonus-credit claimants', '2022-08-16', null, true),
  ('LNK-010', 'POL-003', 'DOC-002', 'implements', 'T.D. 10024 includes energy-community credit-increase rules for sections 45Y and 48E.', '45Y and 48E energy-community bonus claimants', '2025-01-15', null, true),
  ('LNK-011', 'POL-003', 'DOC-008', 'implements', 'Notice 2025-31 is the prior annual update; Notice 2026-39 replaces its current Statistical Area list while preserving specified coal-closure appendices in the cumulative framework.', 'Historical Statistical Area status and cumulative Coal Closure category determinations', '2025-06-23', null, false),
  ('LNK-012', 'POL-003', 'DOC-009', 'supersedes', 'Notice 2026-39 supersedes the prior Statistical Area list for current status and adds new Coal Closure and correction tracts without displacing the cumulative earlier coal-closure appendices it identifies.', 'Current Statistical Area status from June 9, 2026 and additional Coal Closure category tracts', '2026-06-09', null, true),
  ('LNK-013', 'POL-004', 'DOC-010', 'implements', 'Commerce issued the four-country antidumping duty orders, subject to the specified July 2025 corrections.', 'Covered CSPV cells and modules from Cambodia, Malaysia, Thailand, and Vietnam under the AD orders', '2025-06-24', null, true),
  ('LNK-014', 'POL-004', 'DOC-011', 'implements', 'Commerce issued the separate four-country countervailing duty orders.', 'Covered CSPV cells and modules from Cambodia, Malaysia, Thailand, and Vietnam under the CVD orders', '2025-06-24', null, true),
  ('LNK-015', 'POL-004', 'DOC-012', 'amends', 'The correction amends specified scope and exclusion portions of the June 2025 AD order notice only.', 'AD orders for Cambodia, Malaysia, Thailand, and Vietnam CSPV products', '2025-07-07', null, true),
  ('LNK-016', 'POL-004', 'DOC-013', 'decides', 'USITC Publication 5631 contains the Commission''s final injury and threat determinations and supporting views.', 'Final injury and threat determinations for the four-country AD/CVD investigations', '2025-06-09', null, true),
  ('LNK-017', 'POL-004', 'DOC-014', 'interprets', 'The USITC news release summarizes the affirmative determinations documented in Publication 5631.', 'Final injury and threat determinations for the four-country investigations', '2025-05-20', null, false),
  ('LNK-018', 'POL-004', 'DOC-015', 'interprets', 'Commerce''s release summarizes the final affirmative AD/CVD determinations that preceded the formal orders.', 'Four-country CSPV AD/CVD investigations', '2025-04-21', '2025-06-24', false),
  ('LNK-019', 'POL-005', 'DOC-016', 'enacts', 'Order No. 2023 establishes the order-wide interconnection reforms.', 'order_wide', '2023-11-06', null, true),
  ('LNK-020', 'POL-005', 'DOC-017', 'amends', 'The October 25, 2023 order sets Order No. 2023 aside in part to extend compliance-filing deadlines.', 'order_wide', '2023-10-25', null, false),
  ('LNK-021', 'POL-005', 'DOC-018', 'amends', 'Order No. 2023-A modifies and clarifies the final rule.', 'order_wide', '2024-05-16', null, true),
  ('LNK-022', 'POL-005', 'DOC-019', 'amends', 'The August 20, 2024 errata notice makes additional revisions to the pro forma LGIP, LGIA, and SGIA.', 'order_wide', null, null, false),
  ('LNK-023', 'POL-005', 'DOC-020', 'implements', 'The June 2026 FERC statement reports that the rulewide compliance process remains incomplete.', 'order_wide', '2026-06-18', null, false),
  ('LNK-024', 'POL-005', 'DOC-021', 'challenges', 'The D.C. Circuit oral-argument record documents judicial review of Order No. 2023.', 'case_specific', '2025-09-26', null, false),
  ('LNK-025', 'POL-005', 'DOC-022', 'interprets', 'FERC''s May 2026 brief reports that the Order No. 2023 challenges remained pending after argument.', 'case_specific', '2026-05-20', null, false),
  ('LNK-026', 'POL-006', 'DOC-023', 'enacts', 'Order No. 1920 establishes long-term regional planning and cost-allocation reforms.', 'order_wide', '2024-08-12', null, true),
  ('LNK-027', 'POL-006', 'DOC-024', 'amends', 'Order No. 1920-A modifies and clarifies the final rule on rehearing.', 'order_wide', '2025-01-06', null, true),
  ('LNK-028', 'POL-006', 'DOC-025', 'amends', 'Order No. 1920-B further addresses rehearing of and clarifies Order No. 1920-A.', 'order_wide', '2025-04-11', null, true),
  ('LNK-029', 'POL-006', 'DOC-026', 'implements', 'FERC''s schedule describes the two order-wide compliance filings and regional extensions.', 'order_wide', '2025-06-16', null, false),
  ('LNK-030', 'POL-006', 'DOC-027', 'challenges', 'FERC''s current case page records consolidated Fourth Circuit challenges to the Order No. 1920 legal chain.', 'case_specific', '2026-01-05', null, false),
  ('LNK-031', 'POL-006', 'DOC-028', 'challenges', 'FERC''s respondent brief addresses the consolidated petitions for review of Orders No. 1920, 1920-A, and 1920-B.', 'case_specific', '2026-01-05', null, false),
  ('LNK-032', 'POL-007', 'DOC-029', 'implements', 'Executive Order directs the CEQ actions and agency-procedure coordination comprising this policy transition.', 'government_wide', '2025-01-20', null, true),
  ('LNK-033', 'POL-007', 'DOC-030', 'implements', 'Final CEQ rule removes the former government-wide CEQ regulations.', 'government_wide', '2026-01-08', null, true),
  ('LNK-034', 'POL-007', 'DOC-031', 'implements', 'DOI finalizes DOI-only procedures following the CEQ rescission.', 'Department of the Interior', '2026-02-24', null, true),
  ('LNK-035', 'POL-007', 'DOC-032', 'decides', 'Supreme Court decision supplies binding NEPA judicial-review precedent but does not decide the CEQ rescission.', 'federal_NEPA_judicial_review', '2025-05-29', null, false),
  ('LNK-036', 'POL-007', 'DOC-033', 'interprets', 'Current CEQ guidance explains the nonbinding, agency-specific implementation transition after rescission.', 'government_wide_agency_guidance', '2025-09-29', null, true),
